'use client';
import { useEffect, useState } from 'react';

type Summary = {available:boolean;dataset?:string;source_rows?:number;purchase_rows?:number;customers?:number;repeat_customers?:number;at_risk_customers?:number;date_min?:string;date_max?:string;segment_counts?:Record<string,number>;definitions?:Record<string,string>;model_status?:string;prediction_available?:boolean;shap_available?:boolean;evaluation_available?:boolean;evaluation?:any};
type Customer = {"Customer ID":number;Country:string;RecencyDays:number;Frequency:number;Monetary:number;Segment:string;R_Score:number;F_Score:number;M_Score:number};
type Journey = {periods:{Month:string;Segment:string;customers:number}[];transitions:{From:string;To:string;count:number}[];customers:Record<string,unknown>[]};
type DeepDive = {orders:number;gross_sales:number;average_order_value:number;average_units_per_order:number;unique_products:number|null;cancellation_invoice_count:number;return_row_count:number;returned_value_abs:number;currency?:string|null;dataset?:string;monthly:{Month:string;revenue:number;orders:number;customers:number;units:number}[];countries:any[];products:any[];journeys:Journey;all_customers:Customer[]};
type Snapshot = Summary & {deep_dive:DeepDive};
const nav = [
 ['Overview','▦'],['Customer segments','◉'],['Temporal journeys','↗'],['Prediction & churn','⌁'],['Explainable AI','✳'],['Retention advisor','✦'],['Model evaluation','▤'],['Dataset','▧']
];
const segmentNames=['Champions','Loyal','Potential Loyalists','Needs Attention','At Risk'];
const api = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
const money=(n:number,currency?:string|null)=>new Intl.NumberFormat('en-GB',currency?{style:'currency',currency,maximumFractionDigits:0}:{maximumFractionDigits:0}).format(n||0);
export default function Home(){
 const [active,setActive]=useState('Overview'); const [summary,setSummary]=useState<Summary|null>(null); const [customers,setCustomers]=useState<Customer[]>([]); const [countries,setCountries]=useState<string[]>([]); const [snapshot,setSnapshot]=useState<Snapshot|null>(null); const [deepDive,setDeepDive]=useState<DeepDive|null>(null); const [offlineSnapshot,setOfflineSnapshot]=useState(false); const [loading,setLoading]=useState(true); const [error,setError]=useState(''); const [uploading,setUploading]=useState(false); const [uploadMessage,setUploadMessage]=useState(''); const [uploadError,setUploadError]=useState(''); const [query,setQuery]=useState(''); const [segmentFilter,setSegmentFilter]=useState(''); const [countryFilter,setCountryFilter]=useState(''); const [periodFilter,setPeriodFilter]=useState(''); const [predictedOnly,setPredictedOnly]=useState(false); const [selected,setSelected]=useState<number|null>(null); const [detail,setDetail]=useState<any>(null); const [customerAdvice,setCustomerAdvice]=useState<any>(null); const [customerAdviceLoading,setCustomerAdviceLoading]=useState(false); const [journey,setJourney]=useState<Journey|null>(null); const [journeyLoading,setJourneyLoading]=useState(false); const [journeyCustomer,setJourneyCustomer]=useState<number|null>(null); const [customerJourney,setCustomerJourney]=useState<any[]>([]); const [customerJourneyLoading,setCustomerJourneyLoading]=useState(false); const [predictionQueue,setPredictionQueue]=useState<any[]>([]); const [predictionQueueTotal,setPredictionQueueTotal]=useState(0); const [predictionQueueLoading,setPredictionQueueLoading]=useState(false); const [predictionQueueMessage,setPredictionQueueMessage]=useState(''); const [explanationTarget,setExplanationTarget]=useState<'next'|'inactivity'>('next'); const [copiedBrief,setCopiedBrief]=useState(false); const [copyError,setCopyError]=useState(''); const [segmentSort,setSegmentSort]=useState('recency'); const [segmentPage,setSegmentPage]=useState(0); const [globalShap,setGlobalShap]=useState<any>(null); const [globalShapLoading,setGlobalShapLoading]=useState(false);
 useEffect(()=>{let cancelled=false;(async()=>{let staticData:Snapshot|null=null;try{const r=await fetch('/analytics_snapshot.json');if(r.ok)staticData=await r.json();}catch{}if(cancelled)return;if(staticData){setSnapshot(staticData);setDeepDive(staticData.deep_dive);setSummary(staticData);setCustomers(staticData.deep_dive.all_customers||[]);setCountries([...new Set((staticData.deep_dive.all_customers||[]).map(c=>c.Country))].sort());setJourney(staticData.deep_dive.journeys);setOfflineSnapshot(true);}try{const r=await fetch(api+'/api/summary');if(!r.ok)throw new Error('API unavailable');const live=await r.json();if(!cancelled){setSummary(live);setOfflineSnapshot(false);setError('');}const report=await fetch(api+'/api/report');if(report.ok&&!cancelled){const d=await report.json();setDeepDive(d);setJourney(d.journeys);}}catch(e:any){if(!cancelled&&!staticData)setError(e.message||'API unavailable');}finally{if(!cancelled)setLoading(false);}fetch(api+'/api/filters').then(r=>r.ok?r.json():null).then(x=>{if(x&&!cancelled)setCountries(x.countries||[])}).catch(()=>{});})();return()=>{cancelled=true}},[]);
 async function uploadSalesFile(file?:File){if(!file)return;setUploading(true);setUploadError('');setUploadMessage('');try{const res=await fetch(`${api}/api/dataset/upload?filename=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});const result=await res.json();if(!res.ok)throw new Error(result.detail||'Upload failed.');const [s,r,f]=await Promise.all([fetch(api+'/api/summary'),fetch(api+'/api/report'),fetch(api+'/api/filters')]);if(!s.ok||!r.ok)throw new Error('File uploaded, but Project could not refresh its report.');const [nextSummary,nextReport]=await Promise.all([s.json(),r.json()]);setSummary(nextSummary);setDeepDive(nextReport);setSnapshot(prev=>prev?{...prev,...nextSummary,deep_dive:nextReport}:prev);setJourney(nextReport.journeys);if(f.ok){const nextFilters=await f.json();setCountries(nextFilters.countries||[]);}setCustomers(nextReport.all_customers||[]);setOfflineSnapshot(false);setError('');setSelected(null);setDetail(null);setUploadMessage(`Loaded ${result.dataset} · ${result.purchase_rows.toLocaleString()} purchase rows`);}catch(e:any){setUploadError(e.message||'Upload failed.');}finally{setUploading(false);}}
 useEffect(()=>{const params=new URLSearchParams({limit:active==='Customer segments'?'10000':active==='Prediction & churn'||active==='Explainable AI'||active==='Retention advisor'?'100':'15'});if(active==='Customer segments'||active==='Prediction & churn'||active==='Explainable AI'||active==='Retention advisor'){if(query)params.set('search',query);if(active==='Customer segments'){if(segmentFilter)params.set('segment',segmentFilter);if(countryFilter)params.set('country',countryFilter);if(periodFilter)params.set('activity_period_days',periodFilter);if(predictedOnly)params.set('has_prediction','true');}if((active==='Prediction & churn'||active==='Explainable AI')&&!offlineSnapshot&&Boolean(summary?.prediction_available))params.set('has_prediction','true');}fetch(`${api}/api/customers?${params}`).then(r=>r.ok?r.json():Promise.reject()).then(c=>setCustomers(c.items||[])).catch(()=>{if(snapshot){const term=query.trim().toLowerCase();setCustomers(snapshot.deep_dive.all_customers.filter(c=>(!predictedOnly||active!=='Customer segments')&&(!term||String(c['Customer ID']).includes(term))&&(!segmentFilter||c.Segment===segmentFilter)&&(!countryFilter||c.Country===countryFilter)&&(!periodFilter||c.RecencyDays<=Number(periodFilter))))}});},[active,query,segmentFilter,countryFilter,periodFilter,predictedOnly,snapshot,offlineSnapshot,summary]);
 useEffect(()=>{setSegmentPage(0)},[query,segmentFilter,countryFilter,periodFilter,predictedOnly]);
 useEffect(()=>{if(active!=='Temporal journeys'||journey)return;setJourneyLoading(true);fetch(api+'/api/journeys').then(async r=>{if(!r.ok)throw new Error('Temporal profiles could not be loaded.');setJourney(await r.json())}).catch(()=>setJourney(snapshot?.deep_dive.journeys||{periods:[],transitions:[],customers:[]})).finally(()=>setJourneyLoading(false));},[active,journey,snapshot]);
 useEffect(()=>{if(active!=='Prediction & churn')return;let cancelled=false;setPredictionQueueLoading(true);setPredictionQueueMessage('');const params=new URLSearchParams({limit:'200'});if(query.trim())params.set('search',query.trim());fetch(`${api}/api/predictions/queue?${params}`).then(async r=>{const data=await r.json();if(!r.ok)throw new Error(data.detail||'Could not load the prediction queue.');if(!cancelled){setPredictionQueue(data.items||[]);setPredictionQueueTotal(data.total||0);setPredictionQueueMessage(data.message||'');}}).catch(e=>{if(!cancelled){setPredictionQueue([]);setPredictionQueueTotal(0);setPredictionQueueMessage(e.message||'Prediction queue is unavailable.')}}).finally(()=>{if(!cancelled)setPredictionQueueLoading(false)});return()=>{cancelled=true}},[active,query,summary]);
 useEffect(()=>{if(active!=='Explainable AI'&&active!=='Customer segments')return;let cancelled=false;setGlobalShap(null);setGlobalShapLoading(true);fetch(`${api}/api/explainability/global`).then(async r=>{const data=await r.json();if(!r.ok)throw new Error(data.detail||'Global SHAP importance could not be loaded.');if(!cancelled)setGlobalShap(data)}).catch(()=>{if(!cancelled)setGlobalShap({available:false})}).finally(()=>{if(!cancelled)setGlobalShapLoading(false)});return()=>{cancelled=true}},[active,offlineSnapshot,summary]);
 async function chooseCustomer(id:number){setSelected(id);setDetail(null); const endpoint=active==='Retention advisor'?'recommendations':'predictions'; try{const r=await fetch(`${api}/api/${endpoint}/${id}`);setDetail(await r.json())}catch{const profile=snapshot?.deep_dive.all_customers.find(c=>c['Customer ID']===id);setDetail({message:active==='Retention advisor'?'Live recommendation service is unavailable; inspect this customer profile for evidence.':'Validated prediction outputs are not available.',profile})}}
 async function copyRetentionBrief(){if(!detail||selected==null)return;const profile=customers.find(c=>c['Customer ID']===selected);const text=[`Project retention review · Customer ${selected}`,`Provider: ${detail.provider||'Rule-based fallback'}`,`Priority: ${detail.priority||'Standard'}`,`Observed segment: ${detail.observed_profile?.segment||profile?.Segment||'Unavailable'}`,`Recency: ${detail.observed_profile?.recency_days??profile?.RecencyDays??'Unavailable'} days`,`Invoices: ${detail.observed_profile?.invoice_frequency??profile?.Frequency??'Unavailable'}`,`Observed spend: ${detail.observed_profile?.monetary_value??profile?.Monetary??'Unavailable'}`,...(detail.evidence||[]).map((x:string)=>`Evidence: ${x}`),...(detail.recommendations||[]).map((x:string,i:number)=>`Action ${i+1}: ${x}`),`Note: ${detail.disclaimer||'Recommendations do not establish causal impact.'}`].join('\n');setCopyError('');try{await navigator.clipboard.writeText(text);setCopiedBrief(true);window.setTimeout(()=>setCopiedBrief(false),1800)}catch{setCopyError('Clipboard access is unavailable in this browser context.')}}
 async function chooseJourney(id:number){setJourneyCustomer(id);setCustomerJourney([]);setCustomerJourneyLoading(true);try{const r=await fetch(`${api}/api/journeys?customer_id=${id}`);if(!r.ok)throw new Error();const d=await r.json();setCustomerJourney(d.customers||[])}catch{setCustomerJourney(snapshot?.deep_dive.journeys.customers.filter((r:any)=>Number(r['Customer ID'])===id)||[])}finally{setCustomerJourneyLoading(false)}}
 async function chooseSegmentCustomer(id:number){setCustomerAdvice(null);setCustomerAdviceLoading(true);const advice=fetch(`${api}/api/recommendations/${id}`).then(r=>r.ok?r.json():null).then(setCustomerAdvice).catch(()=>setCustomerAdvice(null)).finally(()=>setCustomerAdviceLoading(false));await Promise.all([chooseCustomer(id),chooseJourney(id),advice]);}
 const filtered=customers; const journeyProfiles=offlineSnapshot?customers.filter(c=>(journey?.customers||[]).some((r:any)=>Number(r['Customer ID'])===c['Customer ID'])):customers; const sortedSegmentCustomers=[...filtered].sort((a,b)=>segmentSort==='spend'?b.Monetary-a.Monetary:segmentSort==='frequency'?b.Frequency-a.Frequency:b.RecencyDays-a.RecencyDays); const segmentPageSize=25; const segmentPageCount=Math.max(1,Math.ceil(sortedSegmentCustomers.length/segmentPageSize)); const visibleSegmentCustomers=sortedSegmentCustomers.slice(segmentPage*segmentPageSize,(segmentPage+1)*segmentPageSize);
 const title = active === 'Overview'?'Executive dashboard':active;
 const predictionsReady=!offlineSnapshot&&Boolean(summary?.prediction_available); const shapReady=!offlineSnapshot&&Boolean(summary?.shap_available); const evaluationReady=!offlineSnapshot&&Boolean(summary?.evaluation_available); const retentionReady=!offlineSnapshot&&Boolean(summary?.available);
 const pipelineSteps=[
  {status:'READY',state:'ready',description:'Workbook loaded and purchase rows filtered'},
  {status:'READY',state:'ready',description:'Relative RFM snapshots and observed monthly journeys available'},
  {status:predictionsReady?'READY':offlineSnapshot?'API REQUIRED':'PENDING',state:predictionsReady?'ready':offlineSnapshot?'blocked':'retry',description:predictionsReady?'Chronological next-segment and inactivity models are available':'Connect the live API to load trained prediction artifacts'},
  {status:shapReady?'READY':offlineSnapshot?'API REQUIRED':'PENDING',state:shapReady?'ready':offlineSnapshot?'blocked':'retry',description:shapReady?'Global and customer-level SHAP evidence is available':'Connect the live API to load model explanations'},
  {status:retentionReady?'READY':offlineSnapshot?'API REQUIRED':'PENDING',state:retentionReady?'ready':offlineSnapshot?'blocked':'retry',description:retentionReady?'Evidence-grounded recommendations use observed behaviour and available model evidence; LLM is optional':'Connect the live API to generate evidence-grounded retention advice'}
 ];
 const pipelineComplete=predictionsReady&&shapReady&&evaluationReady&&retentionReady;
 return <div className="shell"><aside className="sidebar"><div className="brand"><div className="brand-mark">P</div><div><strong>Project</strong><span>Customer intelligence</span></div></div><div className="nav-label">WORKSPACE</div><nav>{nav.map(([name,icon])=><button key={name} className={active===name?'nav-item active':'nav-item'} onClick={()=>setActive(name)}><span className="nav-icon">{icon}</span>{name}{name==='Prediction & churn'||name==='Explainable AI'?<span className="locked">—</span>:null}</button>)}</nav><div className="sidebar-bottom"><div className="dataset-mini"><span className="live-dot"/> Active sales dataset <strong>{summary?.dataset||'Online Retail II'}</strong><small>{offlineSnapshot?'Snapshot · connect API to upload':'Upload CSV or Excel · local only'}</small><input id="sales-upload" type="file" accept=".csv,.xlsx,.xlsm" hidden onChange={e=>{uploadSalesFile(e.target.files?.[0]);e.currentTarget.value='';}}/><button className="text-button" disabled={uploading} onClick={()=>document.getElementById('sales-upload')?.click()}>{uploading?'Loading…':'Upload sales data'}</button></div><div className="user"><div className="avatar">DR</div><div><strong>Research team</strong><small>Local workspace</small></div><span>•••</span></div></div></aside>
 <main className="main"><header className="topbar"><div className="crumb">Workspace <span>/</span> {title}</div><div className="top-actions"><span className="status"><i/> {offlineSnapshot?'Actual data · offline snapshot':'Local prototype'}</span><button className="icon-button" aria-label="Notifications">♧</button><div className="avatar small">DR</div></div></header>
 <div className="content"><div className="page-heading"><div><div className="eyebrow">CUSTOMER ANALYTICS <span>•</span> RESEARCH MODE</div><h1>{title}</h1><p>{active==='Overview'?'Track customer value, observe behavioural change, and prioritize retention with evidence.':pageDescription(active)}</p></div><button className="period">All observed data <span>⌄</span></button></div>
 {offlineSnapshot&&<div className="notice"><b>Showing the actual dataset snapshot</b><span>Observed customer records and historical summaries are loaded locally. Connect the FastAPI service to load the current prediction, SHAP, and model-evaluation artifacts.</span></div>}
 {error&&<div className="notice error"><b>Dataset unavailable</b><span>{error}. Start the FastAPI service and check PULSEIQ_DATA_PATH.</span></div>}
 {loading?<div className="notice">Loading local customer data…</div>:null}
 {uploadError&&<div className="notice error"><b>Could not load sales file</b><span>{uploadError}</span></div>}{uploadMessage&&<div className="notice"><b>Sales report refreshed</b><span>{uploadMessage}</span></div>}
 {active==='Overview'&&<>
 <div className="metric-grid"><Metric label="Unique customers" value={fmt(summary?.customers)} caption="With customer IDs" icon="◉" tone="blue"/><Metric label="Repeat customers" value={fmt(summary?.repeat_customers)} caption="More than one invoice" icon="↻" tone="green"/><Metric label="Needs attention" value={fmt(summary?.at_risk_customers)} caption="Needs Attention + At Risk†" icon="⚑" tone="amber"/><Metric label="Model status" value={offlineSnapshot?'API required':predictionsReady?'Evaluated':'Not trained'} caption={offlineSnapshot?'Live model status unavailable':predictionsReady?'Chronological models available':'Predictions unavailable'} icon="⌁" tone="slate"/></div>
 <div className="dashboard-grid"><section className="panel segment-panel"><div className="panel-head"><div><h2>Customer segments</h2><p>Relative RFM quintiles across the full observed period</p></div><button className="text-button" onClick={()=>setActive('Customer segments')}>Explore segments <span>→</span></button></div><SegmentBars counts={summary?.segment_counts||{}}/></section><section className="panel pipeline-panel"><div className="panel-head"><div><h2>Analytics pipeline</h2><p>Understand → Predict → Explain → Act</p></div><span className={'tag '+(pipelineComplete?'pipeline-ready-tag':'retry-tag')}>{pipelineComplete?'PIPELINE READY':offlineSnapshot?'LIVE API REQUIRED':'IN PROGRESS'}</span></div><div className="pipeline">{['Data cleaning','Temporal profiles','Prediction','Explainability','Retention'].map((x,i)=>{const step=pipelineSteps[i];return <div className="pipeline-row" key={x}><span className={'pipeline-number '+(i<2||step.state==='ready'?'done':'')}>{i<2||step.state==='ready'?'✓':i===2&&!offlineSnapshot?'!':i+1}</span><div><b>{x}</b><small>{step.description}</small></div><span className={'pstatus '+step.state}>{step.status}</span>{i===4&&retentionReady&&<button className="text-button pipeline-link" onClick={()=>setActive('Retention advisor')}>Open advisor →</button>}</div>})}</div></section></div>
 <section className="panel attention-panel"><div className="panel-head"><div><h2>Customers requiring attention</h2><p>Observed Needs Attention and At Risk customers, ordered by days since last purchase.</p></div><button className="text-button" onClick={()=>{setSegmentFilter('');setActive('Customer segments')}}>Review at-risk segments <span>→</span></button></div><CustomerTable rows={[...customers].filter(c=>c.Segment==='Needs Attention'||c.Segment==='At Risk').sort((a,b)=>b.RecencyDays-a.RecencyDays).slice(0,5)} onSelect={chooseCustomer}/></section>
 {deepDive&&<DeepDivePanel data={deepDive}/>}
 </>}
 {active==='Customer segments'&&<>
 <section className="panel segment-overview"><div className="panel-head"><div><h2>Explore customer groups</h2><p>Select a segment to focus the customer list. Segment labels are relative RFM profiles, not fixed business rules.</p></div><span className="tag">{fmt(summary?.customers)} CUSTOMERS</span></div><SegmentExplorer counts={summary?.segment_counts||{}} selected={segmentFilter} onSelect={name=>setSegmentFilter(segmentFilter===name?'':name)}/><div className="segment-method-note"><b>How to read these groups</b><span>Recency, invoice frequency and monetary value are scored in quintiles for this dataset. “At Risk” and “Needs Attention” describe relative purchasing patterns; they are not model predictions.</span></div></section>
 <div className="segments-workspace"><section className="panel segment-table-panel"><div className="panel-head"><div><h2>{segmentFilter||'All customer profiles'}</h2><p>Search, filter and sort the current dataset to find a customer profile.</p></div><span className="tag">{fmt(filtered.length)} MATCHES</span></div><div className="table-tools segment-filters"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search customer ID…"/><select value={segmentFilter} onChange={e=>setSegmentFilter(e.target.value)}><option value="">All segments</option>{segmentNames.map(x=><option key={x}>{x}</option>)}</select><select value={countryFilter} onChange={e=>setCountryFilter(e.target.value)}><option value="">All countries</option>{countries.map(x=><option key={x}>{x}</option>)}</select><select value={periodFilter} onChange={e=>setPeriodFilter(e.target.value)}><option value="">Any recency</option><option value="30">Purchased in last 30 observed days</option><option value="90">Purchased in last 90 observed days</option><option value="180">Purchased in last 180 observed days</option><option value="365">Purchased in last 365 observed days</option></select><select value={predictedOnly?'true':'false'} onChange={e=>setPredictedOnly(e.target.value==='true')}><option value="false">All customers</option><option value="true">Customers with predictions</option></select><select value={segmentSort} onChange={e=>setSegmentSort(e.target.value)}><option value="recency">Sort: longest recency</option><option value="spend">Sort: highest spend</option><option value="frequency">Sort: most invoices</option></select></div><CustomerTable rows={visibleSegmentCustomers} onSelect={chooseSegmentCustomer}/><div className="segment-pagination"><span>Showing {filtered.length?segmentPage*segmentPageSize+1:0}–{Math.min((segmentPage+1)*segmentPageSize,filtered.length)} of {fmt(filtered.length)}</span><div><button disabled={segmentPage===0} onClick={()=>setSegmentPage(Math.max(0,segmentPage-1))}>← Previous</button><b>{segmentPage+1} / {segmentPageCount}</b><button disabled={segmentPage+1>=segmentPageCount} onClick={()=>setSegmentPage(Math.min(segmentPageCount-1,segmentPage+1))}>Next →</button></div></div></section>
 <aside className="segments-customer-detail">{selected&&detail?.profile?<><CustomerProfileCard profile={detail.profile} customerId={selected}/><CustomerIntelligence detail={detail} globalShap={globalShap} globalShapLoading={globalShapLoading} journey={customerJourney} journeyLoading={customerJourneyLoading} advice={customerAdvice} adviceLoading={customerAdviceLoading}/></>:<section className="panel segment-detail-empty"><div className="empty-icon">◉</div><h2>Customer detail</h2><p>Select any row to open its RFM profile, observed monthly journey, prediction, explanation and recommendation when available.</p></section>}</aside></div>
 </>}
 {active==='Temporal journeys'&&(journeyLoading?<div className="notice">Calculating monthly historical customer states… This can take a little while on first load.</div>:journey?.periods.length?<>
 <section className="journey-intro"><div><span className="eyebrow">CUSTOMER BEHAVIOUR OVER TIME · {offlineSnapshot?'SNAPSHOT':'LIVE DATA'}</span><h2>Follow how customer value changes</h2><p>Compare observed monthly RFM states, inspect the most common transitions, then open an individual customer’s history.</p></div><div className="journey-period"><b>{journey.periods[0]?.Month} — {journey.periods[journey.periods.length-1]?.Month}</b><span>{journey.periods.length} observed months · rolling 12-month profiles</span></div></section>
 <JourneySummary periods={journey.periods} transitions={journey.transitions}/>
 <div className="journey-workspace"><section className="panel journey-chart-panel"><div className="panel-head"><div><h2>Segment composition by month</h2><p>Observed customer counts in each monthly rolling-window profile.</p></div><span className="tag">OBSERVED STATES</span></div><JourneyChart periods={journey.periods}/><div className="journey-method"><b>Reading this chart</b><span>Each bar is a month. Its colored bands show how many observed customer profiles fell in each relative RFM segment. A change in count does not by itself mean the same customers moved between segments.</span></div></section>
 <section className="panel journey-transition-panel"><div className="panel-head"><div><h2>Most common transitions</h2><p>Adjacent observed monthly states, pooled across customers.</p></div><span className="tag">{journey.transitions.length} FLOWS</span></div><TransitionList transitions={journey.transitions}/></section>
 <section className="panel journey-customer-panel"><div className="panel-head"><div><h2>Explore a customer journey</h2><p>{offlineSnapshot?'Choose a customer with a representative history in this snapshot.':'Choose any customer to calculate their monthly history.'}</p></div><span className="tag">{(offlineSnapshot?journeyProfiles:customers).length} AVAILABLE</span></div><CustomerTable rows={(offlineSnapshot?journeyProfiles:customers).slice(0,10)} onSelect={chooseJourney}/></section>
 <section className="panel journey-detail-panel"><div className="panel-head"><div><h2>{journeyCustomer?`Customer ${journeyCustomer}`:'Customer journey detail'}</h2><p>Observed monthly profile states · model predictions are not included.</p></div>{journeyCustomer&&<span className="tag">{customerJourney.length} STATES</span>}</div>{customerJourneyLoading?<div className="select-empty">Loading customer history…</div>:customerJourney.length?<JourneyTimeline rows={customerJourney}/>:<div className="journey-detail-empty"><span className="journey-empty-icon">↗</span><b>{journeyCustomer?'No saved trajectory in this snapshot':'Select a customer to inspect their path'}</b><p>{journeyCustomer?'The API can calculate any customer journey from the source dataset.':'Their monthly segment, recency, invoice frequency and spend will appear here.'}</p></div>}</section></div>
 <section className="journey-footnote"><b>Observed history only</b><span>Transitions summarize historical states. They are descriptive; use Prediction &amp; churn for model estimates of the next segment and 90-day inactivity risk.</span></section>
 </>:<section className="panel unavailable"><div className="empty-icon">↗</div><h2>Historical journeys are unavailable</h2><p>Start the API and ensure the dataset is readable. Monthly historical profiles are computed on first load.</p></section>)}
 {active==='Prediction & churn'&&<>
 <section className="panel prediction-banner"><div><span className="eyebrow">CHRONOLOGICAL CUSTOMER SCORES</span><h2>Find the next likely transition</h2><p>Review customer-level next-segment estimates and 90-day inactivity proxy scores. Select a customer to inspect their current output.</p></div><div className="prediction-actions">{predictionsReady&&<a className="text-button" href={`${api}/api/predictions/export.csv`}>Download prediction file ↓</a>}<button className="text-button" onClick={()=>setActive('Model evaluation')}>Review holdout metrics →</button></div></section>
 <div className="metric-grid"><Metric label="Matching scored customers" value={predictionQueueLoading?'…':predictionQueueTotal?fmt(predictionQueueTotal):'—'} caption={predictionQueue.length< predictionQueueTotal?'Highest inactivity scores loaded first':'Matches current customer search'} icon="⌁" tone="blue"/><Metric label="Current dataset end" value={summary?.date_max||'—'} caption="Observed data cut-off" icon="▦" tone="slate"/><Metric label="Next-segment target" value="Next observed state" caption="Same customer's following monthly segment" icon="↗" tone="green"/><Metric label="Inactivity target" value="90-day proxy" caption="No positive purchase in fully observed horizon" icon="⚑" tone="amber"/></div>
 <div className="dashboard-grid prediction-workspace"><section className="panel"><div className="panel-head"><div><h2>Prediction queue</h2><p>Sorted by the raw 90-day inactivity score; choose a row for the full customer result.</p></div><span className="tag">{predictionQueue.length?'MODEL OUTPUTS':predictionQueueLoading?'LOADING':'NO SCORES'}</span></div><div className="table-tools"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search customer ID…"/><span>{predictionQueue.length?`${predictionQueue.length} of ${predictionQueueTotal} shown`:'Search or wait for scores'}</span></div>{predictionQueueLoading?<div className="select-empty">Loading customer prediction scores…</div>:predictionQueue.length?<PredictionQueueTable rows={predictionQueue} onSelect={chooseCustomer}/>:<div className="select-empty">{predictionQueueMessage||'No prediction outputs are available for this dataset.'}</div>}</section>
 <section className="panel prediction-detail"><div className="panel-head"><div><h2>{selected?`Customer ${selected} · forecast`:'Customer forecast'}</h2><p>Latest available customer-level prediction record</p></div>{detail?.available&&<span className="tag">SCORED</span>}</div>{selected&&detail?.available&&detail.prediction?<><div className="prediction-results"><Fact label="Predicted next segment" value={detail.prediction.PredictedNextSegment||'—'}/><Fact label="Top class probability · raw" value={detail.prediction.PredictedNextSegmentProbability==null?'—':`${(Number(detail.prediction.PredictedNextSegmentProbability)*100).toFixed(1)}%`}/><Fact label="90-day inactivity probability · raw" value={detail.prediction.ChurnProbability90d==null?'Unavailable':`${(Number(detail.prediction.ChurnProbability90d)*100).toFixed(1)}%`}/></div><div className="micro-note">Probabilities are uncalibrated model outputs. “Churn” refers to a 90-day inactivity proxy, not verified contractual churn. See Model Evaluation for time split, class scores and calibration diagnostics.</div></>:<div className="select-empty">{detail?.message||'Choose a customer from the scored queue to view their outputs.'}</div>}</section></div>
 </>}
 {active==='Explainable AI'&&<>
 <section className="panel explainer-intro"><div><span className="eyebrow">LOCAL MODEL EVIDENCE</span><h2>Why did this customer receive that score?</h2><p>Inspect feature-level SHAP contributions for a selected customer's next-segment and inactivity predictions.</p></div><span className={'tag '+(shapReady?'':'retry-tag')}>{shapReady?'SHAP AVAILABLE':'MODEL EVIDENCE UNAVAILABLE'}</span></section>
 <div className="dashboard-grid explanation-workspace"><section className="panel"><div className="panel-head"><div><h2>Choose a scored customer</h2><p>Search by customer ID. Only available prediction records can include local SHAP values.</p></div></div><div className="table-tools"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search customer ID…"/><span>{customers.length} shown</span></div><CustomerTable rows={customers.slice(0,100)} onSelect={chooseCustomer}/></section>
 <div className="explanation-column"><section className="panel"><div className="panel-head"><div><h2>{selected?`Customer ${selected}`:'Customer evidence'}</h2><p>Observed profile beside model outputs</p></div></div>{detail?.profile?<div className="profile-facts"><Fact label="Current segment" value={detail.profile.Segment||'—'}/><Fact label="Recency" value={`${detail.profile.RecencyDays??'—'} days`}/><Fact label="Invoice frequency" value={fmt(detail.profile.Frequency)}/><Fact label="Observed spend" value={money(detail.profile.Monetary||0)}/></div>:<div className="select-empty">Select a customer to pair their score with local explanations.</div>}{detail?.prediction&&<div className="explanation-output"><b>{explanationTarget==='next'?detail.prediction.PredictedNextSegment||'Next-segment output':'90-day inactivity proxy'}</b><span>{explanationTarget==='next'?detail.prediction.PredictedNextSegmentProbability==null?'Raw probability unavailable':`${(Number(detail.prediction.PredictedNextSegmentProbability)*100).toFixed(1)}% raw top-class probability`:detail.prediction.ChurnProbability90d==null?'Score unavailable':`${(Number(detail.prediction.ChurnProbability90d)*100).toFixed(1)}% raw inactivity probability`}</span></div>}</section><section className="panel"><div className="panel-head"><div><h2>Contribution ranking</h2><p>Customer-level evidence when available; global drivers otherwise</p></div></div><div className="explanation-tabs"><button className={explanationTarget==='next'?'selected':''} onClick={()=>setExplanationTarget('next')}>Next segment</button><button className={explanationTarget==='inactivity'?'selected':''} onClick={()=>setExplanationTarget('inactivity')}>90-day inactivity</button></div><ShapPanel detail={detail} target={explanationTarget} global={globalShap} loading={globalShapLoading}/><div className="micro-note">Customer-level bars explain the selected score. Global fallback bars rank drivers across model examples and are not explanations of this customer. SHAP describes model associations, not causes.</div></section></div></div>
 </>}
 {active==='Model evaluation'&&<EvaluationPanel summary={summary}/>}
 {active==='Retention advisor'&&<>
 <section className="panel advisor-intro"><div><span className="eyebrow">EVIDENCE → ACTION</span><h2>Turn a customer signal into a reviewable next step</h2><p>Recommendations use observed customer behaviour and available model output. Choose a customer to prepare an action brief.</p></div><div className="advisor-legend"><span><i className="legend-dot observed"/>Observed evidence</span><span><i className="legend-dot model"/>Model evidence, when available</span><span><i className="legend-dot action"/>Suggested action</span></div></section>
 <div className="advisor-layout retention-workspace"><section className="panel"><div className="panel-head"><div><h2>Customer review list</h2><p>Prioritize customers using current RFM segment and recency.</p></div><span className="tag">OBSERVED PROFILE</span></div><div className="table-tools"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search customer ID…"/><span>{customers.length} shown</span></div><CustomerTable rows={customers.slice(0,100)} onSelect={chooseCustomer}/></section>
 <section className="panel recommendation action-brief"><div className="panel-head"><div><h2>{selected?`Action brief · ${selected}`:'Retention action brief'}</h2><p>{detail?.provider||'Choose a customer to assemble evidence and suggested actions.'}</p></div><div className="brief-actions"><span className="tag">{detail?.provider==='LLM grounded in supplied evidence'?'LLM · GROUNDED':detail?.provider?'RULE-BASED':'AWAITING'}</span>{selected&&detail?.available&&<button className="text-button" onClick={copyRetentionBrief}>{copiedBrief?'Copied ✓':'Copy brief'}</button>}</div></div>{selected&&detail?.available?<><div className="priority-strip"><span>Priority</span><b className={detail.priority==='Review'?'priority-review':''}>{detail.priority||'Standard'}</b><small>Review priority is a triage cue, not estimated treatment impact.</small></div><div className="brief-profile"><Fact label="Current relative segment" value={detail.observed_profile?.segment||customers.find(c=>c['Customer ID']===selected)?.Segment||'—'}/><Fact label="Days since purchase" value={detail.observed_profile?.recency_days==null?(customers.find(c=>c['Customer ID']===selected)?.RecencyDays==null?'—':`${customers.find(c=>c['Customer ID']===selected)?.RecencyDays} days`):`${detail.observed_profile.recency_days} days`}/><Fact label="Observed invoices" value={fmt(detail.observed_profile?.invoice_frequency??customers.find(c=>c['Customer ID']===selected)?.Frequency)}/><Fact label="Observed spend" value={money(detail.observed_profile?.monetary_value??customers.find(c=>c['Customer ID']===selected)?.Monetary??0)}/></div>{detail.predicted_next_segment&&<div className="micro-note">Model evidence: next segment {detail.predicted_next_segment}{detail.next_segment_probability==null?'':` · raw top-class probability ${(Number(detail.next_segment_probability)*100).toFixed(1)}%`}{detail.churn_probability_90d==null?'':` · raw 90-day inactivity ${(Number(detail.churn_probability_90d)*100).toFixed(1)}%`}</div>}<h3>Suggested actions</h3>{(detail.recommendations||[]).map((r:string,i:number)=><div className="recommendation-item" key={i}><span>{i+1}</span><div><b>{r}</b><small>Suggested for review · no impact estimate available</small></div></div>)}<h3>Supporting evidence</h3>{(detail.evidence||[]).length?(detail.evidence||[]).map((r:string,i:number)=><p className="evidence" key={i}>• {r}</p>):<p className="evidence">No additional evidence was returned for this customer.</p>}<small className="advisor-disclaimer">{detail.disclaimer||'Recommendation is decision support and does not establish causality.'}</small>{copyError&&<small className="copy-error">{copyError}</small>}</>:<div className="select-empty">{detail?.message||'Choose a customer to see their observed profile, evidence and suggested actions.'}</div>}</section></div>
 </>}
 {active==='Dataset'&&<><div className="dashboard-grid"><section className="panel"><div className="panel-head"><div><h2>Sales data</h2><p>Upload a transaction-level CSV or Excel workbook to build a report for that dataset.</p></div><span className="tag">{offlineSnapshot?'SNAPSHOT':'ACTIVE FILE'}</span></div><div className="dataset-facts"><Fact label="Active file" value={summary?.dataset||'Not loaded'}/><Fact label="Source rows" value={fmt(summary?.source_rows)}/><Fact label="Positive purchase rows" value={fmt(summary?.purchase_rows)}/><Fact label="Customers" value={fmt(summary?.customers)}/><Fact label="Observed dates" value={`${summary?.date_min||'—'} to ${summary?.date_max||'—'}`}/><Fact label="Distinct invoices" value={fmt(deepDive?.orders)}/><Fact label="Unique products" value={fmt(deepDive?.unique_products||undefined)}/><Fact label="Cancelled invoices" value={fmt(deepDive?.cancellation_invoice_count)}/><Fact label="Return value (absolute)" value={money(deepDive?.returned_value_abs||0,deepDive&&Object.prototype.hasOwnProperty.call(deepDive,'currency')?deepDive.currency:'GBP')}/></div><p className="micro-note">Required columns: Invoice, Quantity, InvoiceDate, Price, Customer ID, Country. Optional: StockCode, Description. Files remain on this local machine.</p><button className="text-button" disabled={uploading} onClick={()=>document.getElementById('sales-upload')?.click()}>{uploading?'Processing file…':'Choose sales file'}</button>{deepDive&&<a className="text-button report-download" href={`${api}/api/report/download`}>Download complete report · JSON</a>}</section><section className="panel"><div className="panel-head"><div><h2>Cleaning definitions</h2><p>Visible assumptions for reproducibility</p></div></div><ul className="definitions">{Object.entries(summary?.definitions||{}).map(([k,v])=><li key={k}><b>{k.replaceAll('_',' ')}</b><span>{v}</span></li>)}</ul></section></div>{deepDive&&<DeepDivePanel data={deepDive}/>}</>}
 <footer>Project · Research prototype <span>† Relative RFM segment rule · Not a validated churn classification</span></footer>
 </div></main></div>
}
function DeepDivePanel({data}:{data:DeepDive}){const span=data.monthly.length?`${data.monthly[0].Month}–${data.monthly[data.monthly.length-1].Month}`:'No dates';const currency=Object.prototype.hasOwnProperty.call(data,'currency')?data.currency:'GBP';return <><div className="metric-grid deep-metrics"><Metric label="Gross sales" value={money(data.gross_sales,currency)} caption="Positive purchase rows · source currency" icon="¤" tone="blue"/><Metric label="Distinct orders" value={fmt(data.orders)} caption="Unique customer invoices" icon="▤" tone="green"/><Metric label="Average order value" value={money(data.average_order_value,currency)} caption="Gross sales ÷ distinct orders" icon="↗" tone="amber"/><Metric label="Returned value" value={money(data.returned_value_abs,currency)} caption={`${fmt(data.return_row_count)} negative-quantity rows`} icon="↶" tone="slate"/></div><div className="dashboard-grid deep-grid"><section className="panel"><div className="panel-head"><div><h2>Sales and order trend</h2><p>Monthly totals · observed purchases only</p></div><span className="tag">{span}</span></div><MonthlyBars rows={data.monthly} currency={currency}/><div className="micro-note">Order counts are distinct invoice numbers in each month. Returns and cancellation invoices are excluded from gross purchase sales.</div></section><section className="panel"><div className="panel-head"><div><h2>Country contribution</h2><p>Top countries by gross purchase revenue</p></div></div><RankedList rows={data.countries} label="Country" value="revenue" currency={currency}/></section></div><div className="dashboard-grid deep-grid"><section className="panel"><div className="panel-head"><div><h2>Top products</h2><p>Ranked by observed gross purchase revenue</p></div></div><div className="rank-table"><table><thead><tr><th>Product</th><th>Orders</th><th>Units</th><th>Revenue</th></tr></thead><tbody>{data.products.slice(0,8).map((p:any,i)=><tr key={`${p.StockCode}-${i}`}><td><b>{p.Description||p.StockCode}</b><small>{p.StockCode}</small></td><td>{fmt(p.orders)}</td><td>{fmt(p.units)}</td><td>{money(p.revenue,currency)}</td></tr>)}</tbody></table></div></section><section className="panel"><div className="panel-head"><div><h2>Basket and product context</h2><p>Dataset scale and purchase behaviour</p></div></div><div className="dataset-facts"><Fact label="Average units per order" value={Number(data.average_units_per_order).toFixed(1)}/><Fact label="Distinct products" value={fmt(data.unique_products||undefined)}/><Fact label="Cancellation invoices" value={fmt(data.cancellation_invoice_count)}/><Fact label="Return rows" value={fmt(data.return_row_count)}/><Fact label="Average order value" value={money(data.average_order_value,currency)}/><Fact label="Return value" value={money(data.returned_value_abs,currency)}/></div></section></div></>}
function MonthlyBars({rows,currency}:{rows:DeepDive['monthly'];currency?:string|null}){const max=Math.max(1,...rows.map(r=>r.revenue));return <div className="monthly-chart"><div className="monthly-bars">{rows.map(r=><div className="monthly-col" key={r.Month} title={`${r.Month}: ${money(r.revenue,currency)} · ${fmt(r.orders)} orders`}><div className="monthly-bar" style={{height:`${Math.max(2,r.revenue/max*100)}%`}}/><small>{r.Month.slice(2)}</small></div>)}</div><div className="axis-note">Monthly gross revenue · bars scale to the highest month</div></div>}
function RankedList({rows,label,value,currency}:{rows:any[];label:string;value:string;currency?:string|null}){const max=Math.max(1,...rows.map(r=>Number(r[value])));return <div className="rank-list">{rows.slice(0,10).map((r,i)=><div className="rank-item" key={r[label]}><div><span>{i+1}</span><b>{r[label]}</b><strong>{money(r[value],currency)}</strong></div><div className="rank-track"><i style={{width:`${Number(r[value])/max*100}%`}}/></div><small>{fmt(r.orders)} orders · {fmt(r.customers)} customers</small></div>)}</div>}
function Metric({label,value,caption,icon,tone}:{label:string,value:string,caption:string,icon:string,tone:string}){return <div className="metric"><div className="metric-top"><span>{label}</span><i className={tone}>{icon}</i></div><strong>{value}</strong><small>{caption}</small></div>}
function SegmentBars({counts}:{counts:Record<string,number>}){const colors=['#4386d7','#53a98d','#8b83ce','#e7a34b','#d97068'];const total=Object.values(counts).reduce((a,b)=>a+b,0)||1;return <div className="segment-list">{['Champions','Loyal','Potential Loyalists','Needs Attention','At Risk'].map((name,i)=>{const n=counts[name]||0;return <div className="segment-row" key={name}><div className="segment-label"><i style={{background:colors[i]}}/><span>{name}</span><b>{fmt(n)}</b><small>{Math.round(n/total*100)}%</small></div><div className="bar-track"><div style={{width:`${Math.max(1,n/total*100)}%`,background:colors[i]}}/></div></div>})}</div>}
function SegmentExplorer({counts,selected,onSelect}:{counts:Record<string,number>;selected:string;onSelect:(name:string)=>void}){const colors=['#4386d7','#53a98d','#8b83ce','#e7a34b','#d97068'];const total=Object.values(counts).reduce((a,b)=>a+b,0)||1;return <div className="segment-explorer">{segmentNames.map((name,index)=>{const count=counts[name]||0;return <button key={name} className={`segment-explorer-card ${selected===name?'chosen':''}`} onClick={()=>onSelect(name)} aria-pressed={selected===name}><span className="segment-explorer-mark" style={{background:colors[index]}}/><span className="segment-explorer-name">{name}</span><b>{fmt(count)}</b><small>{(count/total*100).toFixed(1)}% of current customers</small><i><em style={{width:`${Math.max(count?1:0,count/total*100)}%`,background:colors[index]}}/></i></button>})}</div>}
function PredictionQueueTable({rows,onSelect}:{rows:any[];onSelect:(id:number)=>void}){return <div className="table-wrap"><table className="prediction-queue-table"><thead><tr><th>Customer</th><th>Current segment</th><th>Next segment</th><th>Next-state score · raw</th><th>Inactivity score · raw</th></tr></thead><tbody>{rows.map(row=><tr key={`${row['Customer ID']}-${row.Month}`} onClick={()=>onSelect(Number(row['Customer ID']))}><td><b>#{Math.trunc(Number(row['Customer ID']))}</b><small>{row.Month||'Latest scored period'}</small></td><td><span className={'segment-chip '+String(row.Segment||'').toLowerCase().replaceAll(' ','-')}>{row.Segment||'—'}</span></td><td>{row.PredictedNextSegment||'—'}</td><td><ProbabilityBar value={row.PredictedNextSegmentProbability}/></td><td><ProbabilityBar value={row.ChurnProbability90d}/></td></tr>)}</tbody></table></div>}
function ProbabilityBar({value}:{value:number|string|null|undefined}){const score=Number(value);if(value==null||!Number.isFinite(score))return <span className="probability-missing">Unavailable</span>;const percent=Math.max(0,Math.min(100,score*100));return <div className="probability-cell"><span>{percent.toFixed(1)}%</span><i><b style={{width:`${percent}%`}}/></i></div>}
function CustomerTable({rows,onSelect}:{rows:Customer[];onSelect:(id:number)=>void}){return <div className="table-wrap"><table><thead><tr><th>Customer</th><th>Country</th><th>Recency</th><th>Invoices</th><th>Spend</th><th>RFM scores</th><th>Segment</th></tr></thead><tbody>{rows.map(c=><tr key={c['Customer ID']} onClick={()=>onSelect(c['Customer ID'])}><td><b>#{c['Customer ID']}</b></td><td>{c.Country}</td><td>{c.RecencyDays}d</td><td>{c.Frequency}</td><td>{money(c.Monetary)}</td><td>R{c.R_Score} · F{c.F_Score} · M{c.M_Score}</td><td><span className={'segment-chip '+c.Segment.toLowerCase().replaceAll(' ','-')}>{c.Segment}</span></td></tr>)}</tbody></table>{rows.length===0&&<div className="select-empty">No customers match this search.</div>}</div>}
function Fact({label,value}:{label:string,value:string}){return <div className="fact"><small>{label}</small><b>{value}</b></div>}
function JourneyChart({periods}:{periods:Journey['periods']}){const months=[...new Set(periods.map(x=>x.Month))];const segments=['Champions','Loyal','Potential Loyalists','Needs Attention','At Risk'];const colors=['#4386d7','#53a98d','#8b83ce','#e7a34b','#d97068'];const max=Math.max(1,...months.map(m=>periods.filter(x=>x.Month===m).reduce((sum,x)=>sum+x.customers,0)));return <div className="journey-chart"><div className="chart-legend">{segments.map((segment,index)=><span key={segment}><i style={{background:colors[index]}}/>{segment}</span>)}</div><div className="chart-bars">{months.map(month=>{const total=periods.filter(x=>x.Month===month).reduce((sum,x)=>sum+x.customers,0);return <div className="month-column" key={month} title={`${month}: ${fmt(total)} observed profiles`}><div className="stacked-bar">{segments.map((segment,index)=>{const count=periods.find(x=>x.Month===month&&x.Segment===segment)?.customers||0;return <i title={`${month} · ${segment}: ${fmt(count)}`} key={segment} style={{height:`${count/max*100}%`,background:colors[index]}}/>})}</div><small>{month.slice(2)}</small></div>})}</div><div className="axis-note">Profiles per observed month · hover a band for its segment count</div></div>}
function JourneySummary({periods,transitions}:{periods:Journey['periods'];transitions:Journey['transitions']}){const months=[...new Set(periods.map(x=>x.Month))];const latest=months[months.length-1];const latestRows=periods.filter(x=>x.Month===latest);const latestTotal=latestRows.reduce((sum,x)=>sum+x.customers,0);const changing=transitions.filter(x=>x.From!==x.To).reduce((sum,x)=>sum+x.count,0);const transitionTotal=transitions.reduce((sum,x)=>sum+x.count,0);const latestAtRisk=latestRows.filter(x=>x.Segment==='At Risk'||x.Segment==='Needs Attention').reduce((sum,x)=>sum+x.customers,0);return <div className="journey-metrics"><div className="journey-metric"><span>Observed customer-months</span><b>{fmt(periods.reduce((sum,x)=>sum+x.customers,0))}</b><small>Monthly profile states in this view</small></div><div className="journey-metric"><span>Latest observed profiles</span><b>{fmt(latestTotal)}</b><small>{latest||'—'} · all current segment states</small></div><div className="journey-metric"><span>Observed state changes</span><b>{fmt(changing)}</b><small>{transitionTotal?`${(changing/transitionTotal*100).toFixed(1)}% of adjacent transitions changed segment`:'No adjacent transitions'}</small></div><div className="journey-metric"><span>Needs attention / At Risk</span><b>{fmt(latestAtRisk)}</b><small>{latestTotal?`${(latestAtRisk/latestTotal*100).toFixed(1)}% of latest observed profiles`:'Latest period unavailable'}</small></div></div>}
function TransitionList({transitions}:{transitions:Journey['transitions']}){const top=[...transitions].sort((a,b)=>b.count-a.count).slice(0,8);const max=Math.max(1,...top.map(t=>t.count));return <div className="journey-flows">{top.map((t,i)=><div className="journey-flow" key={`${t.From}-${t.To}`}><div className="journey-flow-heading"><span>{String(i+1).padStart(2,'0')}</span><b>{t.From}</b><em>→</em><b>{t.To}</b><strong>{fmt(t.count)}</strong></div><i><b style={{width:`${t.count/max*100}%`}}/></i></div>)}{!top.length&&<div className="select-empty">No adjacent month transitions found.</div>}</div>}
function JourneyTimeline({rows}:{rows:any[]}){const ordered=[...rows].sort((a,b)=>String(a.Month).localeCompare(String(b.Month)));return <div className="journey-timeline">{ordered.map((row,index)=><div className="journey-state" key={`${row.Month}-${row.Segment}`}><div className="journey-state-marker"><i/></div><div className="journey-state-content"><div><span>{row.Month}</span><b className={'segment-chip '+String(row.Segment).toLowerCase().replaceAll(' ','-')}>{row.Segment}</b></div><p><strong>{row.RecencyDays}d</strong> since purchase <i/> <strong>{fmt(row.Frequency)}</strong> invoices <i/> <strong>{money(Number(row.Monetary)||0)}</strong> observed spend</p></div>{index===ordered.length-1&&<small>LATEST</small>}</div>)}</div>}
function ShapPanel({detail,target,global,loading}:{detail:any;target?:'next'|'inactivity';global:any;loading?:boolean}){const prediction=detail?.prediction;const nextSegment=prediction?.SHAPContributionsNextSegment;const churn=prediction?.SHAPContributions;const hasValues=(value:any)=>value&&typeof value==='object'&&Object.keys(value).length>0;const local=target==='next'?nextSegment:target==='inactivity'?churn:nextSegment||churn;if(hasValues(local))return <div className="shap-targets">{target?<ShapTarget title={target==='next'?'Next-segment prediction':'90-day inactivity model'} values={local}/>:<><ShapTarget title="Next-segment prediction" values={nextSegment}/><ShapTarget title="90-day inactivity model" values={churn}/></>}<div className="micro-note">These are customer-level SHAP contributions. Positive values move the model output upward; negative values move it downward. They describe model associations, not causes.</div></div>;const hasGlobal=target?Boolean(global?.[target]?.length):Boolean(global?.next_segment?.length||global?.inactivity?.length);if(loading&&!global)return <div className="select-empty">Loading saved model feature rankings…</div>;if(hasGlobal)return <div className="global-shap-fallback"><div className="global-shap-note"><b>{detail?'Customer-specific explanation unavailable':'Global model drivers'}</b><span>{detail?(detail.message||'No local contribution record is saved for this customer.'):'Select a customer with a scored prediction to view local SHAP contributions.'} Showing global model drivers below; these describe the model overall, not this customer.</span></div><GlobalShapPanel global={global} target={target}/></div>;return <div className="select-empty">{global?.message||detail?.message||'SHAP values are not available for this customer or dataset.'}</div>}
function GlobalShapPanel({global,target}:{global:any;target?:'next'|'inactivity'}){const items=target?[{key:target,title:target==='next'?'Next-segment model · global drivers':'90-day inactivity model · global drivers',rows:global?.[target]||[]}]:[{key:'next',title:'Next-segment model · global drivers',rows:global?.next_segment||[]},{key:'inactivity',title:'90-day inactivity model · global drivers',rows:global?.inactivity||[]}];return <div className="global-shap-panels">{items.filter(item=>item.rows.length).map(item=><section className="shap-target" key={item.key}><h3>{item.title}</h3><div className="shap-list">{item.rows.slice(0,8).map((row:any)=><div className="shap-row" key={row.feature}><span>{String(row.feature).replaceAll('_',' ')}</span><div><i style={{width:`${Math.max(0,Number(row.mean_abs_shap)||0)/(Math.max(...item.rows.map((x:any)=>Number(x.mean_abs_shap)||0))||1)*100}%`,background:'#668fb5'}}/></div><b>{Number(row.mean_abs_shap).toFixed(3)}</b></div>)}</div></section>)}</div>}

function ShapTarget({title,values}:{title:string;values?:Record<string,number>|null}){const rows=Object.entries(values||{}).filter(([,value])=>Number.isFinite(Number(value))).sort((a,b)=>Math.abs(Number(b[1]))-Math.abs(Number(a[1]))).slice(0,10);if(!rows.length)return null;const max=Math.max(...rows.map(([,value])=>Math.abs(Number(value))),Number.EPSILON);return <section className="shap-target"><h3>{title}</h3><div className="shap-list">{rows.map(([feature,value])=><div className="shap-row" key={feature}><span>{feature.replaceAll('_',' ')}</span><div><i style={{width:`${Math.abs(Number(value))/max*100}%`,background:Number(value)>=0?'#4ca27e':'#d7746a'}}/></div><b>{Number(value).toFixed(3)}</b></div>)}</div></section>}
function EvaluationPanel({summary}:{summary:Summary|null}){const e=summary?.evaluation;const split=e?.split;const models=e?.next_segment?.models;const churn=e?.churn_90d;const dates=split?`Next-segment train ${split.next_segment_train_period?.join(' to ')} (${fmt(split.next_segment_train_rows)} rows), test ${split.next_segment_test_period?.join(' to ')} (${fmt(split.next_segment_test_rows)} rows).`:'';return <section className="panel"><div className="panel-head"><div><h2>Chronological holdout evaluation</h2><p>{e?.evaluation||'Evaluation results are not included in the offline data snapshot.'} {dates}</p></div>{models?<a className="text-button" href={`${api}/api/model-evaluation/download`}>Download evaluation JSON</a>:<span className="tag">API REQUIRED</span>}</div>{models?<><MetricTable title="Next-segment prediction" models={models} keys={['accuracy','macro_precision','macro_recall','macro_f1','multiclass_brier_score','top_label_ece']}/>{Object.entries(models).map(([name,model]:[string,any])=><div key={name}><PerClassTable title={`${name.replaceAll('_',' ')} · per-class scores`} rows={model.per_class||[]} labels={model.label_names}/>{model.confusion_matrix&&<ConfusionTable title={`${name.replaceAll('_',' ')} · confusion matrix`} matrix={model.confusion_matrix} labels={model.label_names||model.class_order}/>}</div>)}{churn?.models&&<><div className="micro-note">90-day inactivity train {churn.train_period?.join(' to ')} ({fmt(churn.train_rows)} rows), test {churn.test_period?.join(' to ')} ({fmt(churn.test_rows)} rows).</div><MetricTable title="90-day inactivity proxy" models={churn.models} keys={['accuracy','precision','recall','f1','roc_auc','pr_auc','brier_score','expected_calibration_error']}/>{Object.entries(churn.models).map(([name,model]:[string,any])=><div key={name}><PerClassTable title={`${name.replaceAll('_',' ')} · per-class scores`} rows={model.per_class||[]} labels={model.label_names}/>{model.confusion_matrix&&<ConfusionTable title={`${name.replaceAll('_',' ')} · confusion matrix`} matrix={model.confusion_matrix} labels={model.label_names||model.class_order}/>}</div>)}</>}<div className="micro-note">The next-segment label is the same customer’s segment in the immediately following observed monthly snapshot. The 90-day target is no positive purchase during a fully observed 90-day horizon. Brier and ECE are calibration diagnostics; predictions are not transformed by a post-hoc calibrator.</div></>:<div className="select-empty">Connect the FastAPI service to load the current chronological evaluation results.</div>}</section>}
function MetricTable({title,models,keys}:{title:string;models:Record<string,any>;keys:string[]}){const names=Object.keys(models);return <div className="metric-table"><h3>{title}</h3><table><thead><tr><th>Model</th>{keys.map(k=><th key={k}>{k.replaceAll('_',' ')}</th>)}</tr></thead><tbody>{names.map(n=><tr key={n}><td>{n.replaceAll('_',' ')}</td>{keys.map(k=><td key={k}>{models[n][k]==null?'—':Number(models[n][k]).toFixed(3)}</td>)}</tr>)}</tbody></table></div>}
function PerClassTable({title,rows,labels}:{title:string;rows:any[];labels?:string[]}){if(!rows.length)return null;return <div className="metric-table"><h3>{title}</h3><table><thead><tr><th>Class</th><th>Precision</th><th>Recall</th><th>F1</th><th>Support</th></tr></thead><tbody>{rows.map(r=><tr key={r.class}><td>{labels?.[Number(r.class)]||r.class}</td><td>{Number(r.precision).toFixed(3)}</td><td>{Number(r.recall).toFixed(3)}</td><td>{Number(r.f1).toFixed(3)}</td><td>{fmt(r.support)}</td></tr>)}</tbody></table></div>}
function ConfusionTable({title,matrix,labels}:{title:string;matrix:number[][];labels:string[]}){return <div className="metric-table"><h3>{title} (actual rows × predicted columns)</h3><div className="table-wrap"><table><thead><tr><th>Actual \ Predicted</th>{labels.map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{matrix.map((row,i)=><tr key={labels[i]}><td>{labels[i]}</td>{row.map((n,j)=><td key={`${i}-${j}`}>{fmt(n)}</td>)}</tr>)}</tbody></table></div></div>}
function CustomerProfileCard({profile,customerId}:{profile:any;customerId:number}){const d=profile.LastPurchase;const lastPurchase=d==null?'—':typeof d==='number'?new Date(d).toISOString().slice(0,10):String(d).slice(0,10);return <div className="profile-card"><div className="profile-heading"><div><h3>Customer {customerId}</h3><p>{profile.Country} · Last purchase {lastPurchase}</p></div><span className={'segment-chip '+String(profile.Segment).toLowerCase().replaceAll(' ','-')}>{profile.Segment}</span></div><div className="profile-facts"><Fact label="Recency" value={`${profile.RecencyDays} days`}/><Fact label="Invoices" value={fmt(profile.Frequency)}/><Fact label="Monetary value" value={money(profile.Monetary)}/><Fact label="RFM scores" value={`R${profile.R_Score} · F${profile.F_Score} · M${profile.M_Score}`}/><Fact label="Average invoice value" value={money(profile.AvgBasketValue)}/><Fact label="Average inter-purchase interval" value={profile.InterPurchaseDays==null?'Single purchase':`${Number(profile.InterPurchaseDays).toFixed(1)} days`}/></div></div>}
function CustomerIntelligence({detail,globalShap,globalShapLoading,journey,journeyLoading,advice,adviceLoading}:{detail:any;globalShap:any;globalShapLoading:boolean;journey:any[];journeyLoading:boolean;advice:any;adviceLoading:boolean}){const prediction=detail?.prediction;return <section className="panel intelligence-panel"><div className="panel-head"><div><h2>Customer intelligence</h2><p>Observed RFM profile, historical changes, model evidence, and suggested action.</p></div></div><div className="dashboard-grid"><section className="panel"><h3>Observed monthly journey</h3>{journeyLoading?<div className="select-empty">Loading observed customer history…</div>:journey.length?<div className="transition-list">{journey.map((row:any)=><div className="transition-row" key={`${row.Month}-${row.Segment}`}><span>{row.Month}</span><b>{row.Segment}</b><strong>{row.RecencyDays}d · {fmt(row.Frequency)} invoices · {money(Number(row.Monetary)||0)}</strong></div>)}</div>:<div className="select-empty">No journey rows are available for this customer.</div>}</section><section className="panel"><h3>Prediction and inactivity risk</h3>{prediction?<div className="prediction-results"><Fact label="Predicted next segment" value={prediction.PredictedNextSegment}/><Fact label="Top-class probability (uncalibrated)" value={`${(Number(prediction.PredictedNextSegmentProbability)*100).toFixed(1)}%`}/><Fact label="90-day inactivity probability (uncalibrated)" value={prediction.ChurnProbability90d==null?'Unavailable':`${(Number(prediction.ChurnProbability90d)*100).toFixed(1)}%`}/></div>:<div className="model-unavailable-inline"><b>Prediction unavailable for this customer</b><span>{detail?.message||'No prediction is available for this customer.'}</span><small>The observed RFM profile, monthly journey and evidence-based retention advice are still available below.</small></div>}</section><section className="panel"><h3>Model explanations</h3><ShapPanel detail={detail} global={globalShap} loading={globalShapLoading}/></section><section className="panel"><h3>Retention Advisor</h3>{adviceLoading?<div className="select-empty">Generating recommendation from customer evidence…</div>:advice?.available?<><p className="provider-note">{advice.provider} · {advice.priority||'Standard'} priority</p>{(advice.recommendations||[]).map((action:string,index:number)=><div className="recommendation-item" key={index}><span>{index+1}</span>{action}</div>)}{(advice.evidence||[]).map((fact:string,index:number)=><p className="evidence" key={index}>• {fact}</p>)}<small>{advice.disclaimer}</small></>:<div className="select-empty">Retention advice is unavailable while the live API is disconnected.</div>}</section></div></section>}
function fmt(value?:number){return value==null?'—':new Intl.NumberFormat('en-GB').format(value)}
function pageDescription(page:string){return ({'Customer segments':'Compare observed customer value and activity using transparent RFM features.','Temporal journeys':'Review customer states across historical observation windows.','Prediction & churn':'Model outputs appear after chronological evaluation.','Explainable AI':'Inspect model evidence and feature contributions.','Retention advisor':'Turn observed customer behaviour into a specific, evidence-grounded next step.','Model evaluation':'Compare static RFM baselines with temporal feature models.','Dataset':'Inspect the source data and the rules used to prepare it.'} as Record<string,string>)[page]||''}
